// Measured: our scaled-down re-implementation of neuron-finder's search on Qwen3-0.6B, CPU, float32, keyword scoring
// in place of the LLM judge. Generated by scripts from the run's JSON files (public/articles/neuron-finding/); do not
// hand-edit numbers. Settings are one candidate neuron at one dose, scored on 8 sampled replies.

export type Src = { settings: number; mean_hit: number; frac_ge_0375: number; best: number }
export type CpuRun = {
  target: string
  bySource: Record<string, Src>
  best: { layer: number; neuron: number; dose: number; hits: number; of: number; src: string }
  nullP95: number
  verdict: string
  totalS: number
  timing: Record<string, number>
  nCandidates: number
  nControls: number
  doses: number[]
  confirmed: { layer: number; neuron: number; dose: number; hits: number; of: number; src: string; verdict: string }[]
  samples: string[]
  layers: number[]
}

